type Evictor[K comparable] interface{ Pick(keys []K) K }

type LRU[K comparable] struct{}

func (LRU[K]) Pick(keys []K) K { return keys[0] }

type Cache[K comparable, V any, P Evictor[K]] struct {
    policy P
    items  map[K]V
}

func (c *Cache[K, V, P]) Victim(keys []K) K { return c.policy.Pick(keys) }
